import{_ as a,o as t,c as o,a0 as s}from"./chunks/framework.CNXp-E7Q.js";const u=JSON.parse('{"title":"The release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function i(n,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-release-model" tabindex="-1">The release model <a class="header-anchor" href="#the-release-model" aria-label="Permalink to &quot;The release model&quot;">​</a></h1><p>bupha releases itself — there is no hosted CI and no release tool in the loop. Two deliberate phases:</p><h2 id="phase-1-—-the-explicit-seed" tabindex="-1">Phase 1 — the explicit seed <a class="header-anchor" href="#phase-1-—-the-explicit-seed" aria-label="Permalink to &quot;Phase 1 — the explicit seed&quot;">​</a></h2><p><code>bupha deploy release</code> runs once, by hand: it reads cargo metadata, topologically orders the workspace&#39;s path-dependency graph, <code>cargo publish</code>es every member, tags <code>{repo}-v{version}</code>, and pushes the tag.</p><p>Why explicit? Publishing is the <strong>only irreversible step</strong> in the whole system. Queues, runs, and statuses are all idempotent and local; a crate version on crates.io is forever. Everything else in bupha fires on push — the seed doesn&#39;t. (<code>--dry-run</code> prints the order and tag without touching anything.)</p><h2 id="phase-2-—-push-driven-forever-after" tabindex="-1">Phase 2 — push-driven forever after <a class="header-anchor" href="#phase-2-—-push-driven-forever-after" aria-label="Permalink to &quot;Phase 2 — push-driven forever after&quot;">​</a></h2><p>From then on a release is <em>just another bupha job</em>: a push to <code>main</code> hits the webhook, queues latest-wins, and runs <code>scripts/release.sh</code> in a detached worktree under the shell runner.</p><p>The script:</p><ol><li>diffs crate paths since the last <code>bupha-v*</code> tag</li><li><code>cargo set-version --bump patch</code> on touched crates only (the cli republishes on any change — it&#39;s the install artifact)</li><li><code>cargo publish</code>es them in dep order</li><li>tags <code>bupha-vX.Y.Z</code>, builds host-arch binaries with <code>cargo dist</code>, uploads to a GitHub Release via <code>gh</code></li></ol><p>The 5-minute sleep at the top isn&#39;t a hack — it&#39;s the debounce window. Combined with <code>queue = &quot;latest&quot;</code> + <code>cancel_running</code>, rapid push bursts collapse to one release of the newest sha; killed runs get an honest &quot;cancelled&quot; status.</p><h2 id="why-this-shape" tabindex="-1">Why this shape <a class="header-anchor" href="#why-this-shape" aria-label="Permalink to &quot;Why this shape&quot;">​</a></h2><ul><li><strong>No release-plz / GHA</strong>: the point of the project is that CI is a local loop — depending on hosted CI to ship it would be self-defeating. <code>release.sh</code> is deliberately boring bash so it can run as a plain <code>cmd</code> under <code>runner.kind = &quot;shell&quot;</code>.</li><li><strong>Latest-wins, not <code>all</code></strong>: a release that misses an intermediate push loses nothing — the tag lands on HEAD, which contains everything. <code>queue = &quot;all&quot;</code> is for pipelines where each sha&#39;s run is individually meaningful.</li><li><strong>Explicit over automatic</strong>: a wrong tag or half-published workspace is far worse than a delayed release; the boundary sits exactly at irreversibility.</li></ul><p>Host prerequisites: <code>cargo-edit</code>, <code>cargo-dist</code>, <code>gh</code>, and <code>CARGO_REGISTRY_TOKEN</code> (env → keyring → env file). Multi-arch binaries arrive when the remote-runner pair lands — see TODO.</p>',13)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
